const lessons=[{"sentences":[{"speaker":"A","text":"We need to design our reading habits survey before the seminar tomorrow.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.541083333333333},{"speaker":"B","text":"Although we discussed paper questionnaires earlier, I think an online form is better.","position":2,"audioStartSeconds":4.741083333333333,"audioEndSeconds":10.144041666666666},{"speaker":"A","text":"An online form will definitely reach more students across the entire campus.","position":3,"audioStartSeconds":10.344041666666667,"audioEndSeconds":15.29325},{"speaker":"B","text":"Let us keep the questions very short because busy people hate long surveys.","position":4,"audioStartSeconds":15.49325,"audioEndSeconds":20.429583333333333},{"speaker":"A","text":"We should ask about daily reading hours and preferred book formats.","position":5,"audioStartSeconds":20.629583333333333,"audioEndSeconds":24.9595},{"speaker":"B","text":"That sounds sensible if we want to compare digital readers with traditional readers.","position":6,"audioStartSeconds":25.1595,"audioEndSeconds":30.06929166666667},{"speaker":"A","text":"How many questions should we include in total for this project?","position":7,"audioStartSeconds":30.269291666666668,"audioEndSeconds":34.302791666666664},{"speaker":"B","text":"Ten questions are enough when respondents have limited time to finish them.","position":8,"audioStartSeconds":34.50279166666667,"audioEndSeconds":39.05175},{"speaker":"A","text":"I can create the digital questionnaire tonight if you write the introduction.","position":9,"audioStartSeconds":39.25175,"audioEndSeconds":43.80070833333333},{"speaker":"B","text":"I will gladly write the introductory text and check the spelling.","position":10,"audioStartSeconds":44.000708333333336,"audioEndSeconds":48.13729166666667},{"speaker":"A","text":"We also need to analyze the data after everyone completes the survey.","position":11,"audioStartSeconds":48.337291666666665,"audioEndSeconds":52.989375},{"speaker":"B","text":"I can handle the charts because I love working with spreadsheets.","position":12,"audioStartSeconds":53.189375,"audioEndSeconds":57.39041666666667},{"speaker":"A","text":"That leaves the final written report for me to write next week.","position":13,"audioStartSeconds":57.59041666666667,"audioEndSeconds":61.726},{"speaker":"B","text":"Everything is perfectly divided because we shared the workload equally.","position":14,"audioStartSeconds":61.926,"audioEndSeconds":66.379125}],"questions":[{"prompt":"What method do the speakers finally choose for their survey?","options":["A paper questionnaire distributed in class.","An online form reaching more students.","Interviews conducted in the campus library."],"answer":"B","evidenceSentence":3,"evidence":"An online form will definitely reach more students across the entire campus.","explanation":"Speaker A khẳng định biểu mẫu trực tuyến sẽ tiếp cận được nhiều sinh viên hơn trên toàn campus."},{"prompt":"Why do they decide to keep the questions short?","options":["Because busy people dislike long surveys.","Because the computer program has limits.","Because the professor requested a short test."],"answer":"A","evidenceSentence":4,"evidence":"Let us keep the questions very short because busy people hate long surveys.","explanation":"Speaker B giải thích rằng những người bận rộn rất ghét các khảo sát dài."},{"prompt":"What specific topic do they decide to include in the survey?","options":["Daily reading hours and book formats.","Library membership costs and opening times.","Favorite authors from past centuries."],"answer":"A","evidenceSentence":5,"evidence":"We should ask about daily reading hours and preferred book formats.","explanation":"Họ đồng ý hỏi về số giờ đọc sách mỗi ngày và định dạng sách ưa thích."},{"prompt":"How many total questions will the survey contain?","options":["Five questions.","Ten questions.","Twenty questions."],"answer":"B","evidenceSentence":8,"evidence":"Ten questions are enough when respondents have limited time to finish them.","explanation":"Speaker B đề xuất mười câu hỏi là đủ khi người trả lời có ít thời gian."},{"prompt":"What task does Speaker B agree to do first?","options":["Create the digital questionnaire.","Write the introductory text.","Analyze all the collected data."],"answer":"B","evidenceSentence":10,"evidence":"I will gladly write the introductory text and check the spelling.","explanation":"Speaker B nhận viết phần giới thiệu và kiểm tra lỗi chính tả."},{"prompt":"How will they handle the final written report?","options":["Speaker A will write it next week.","They will write it together on Sunday.","Speaker B will write it after making charts."],"answer":"A","evidenceSentence":13,"evidence":"That leaves the final written report for me to write next week.","explanation":"Speaker A nhận nhiệm vụ viết báo cáo hoàn chỉnh vào tuần tới."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
